import React, { MouseEventHandler, PropsWithChildren } from "react";
import clsx from "clsx";
import { Banner as BannerStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import useTimeout from "../../lib/hooks/useTimeout";
import { CommonProps } from "../helperTypes";

type Variants = "info" | "warning" | "error" | "success";

type Props = PropsWithChildren<{
  /** Delay in ms before onClose is automatically called. */
  autoHideDuration?: number;
  /** Callback fired when the remove button is clicked. If set, the remove button will be shown. */
  onClose?: () => void;
  /** The color variant */
  variant?: Variants;
}>;

export type BannerProps = Props & CommonProps;

const useStyles = createUseStyles(BannerStyles, "banner");

const RemoveButton = ({
  onClick,
}: {
  onClick: MouseEventHandler<HTMLButtonElement>;
}) => {
  const classes = useStyles();
  return (
    <button
      type="button"
      className={classes.removeBtn}
      aria-label="Remove"
      onClick={onClick}
      onTouchEnd={(e: any) => {
        e.preventDefault();
        onClick && onClick(e);
      }}
      onMouseDown={(e) => {
        e.preventDefault();
        e.stopPropagation();
      }}
    />
  );
};

const Banner = (props: BannerProps) => {
  const {
    className,
    children,
    variant = "info",
    onClose,
    autoHideDuration,
    ...rest
  } = props;
  const classes = useStyles();

  const handleClose = () => onClose && onClose();
  useTimeout(handleClose, autoHideDuration);

  const role = variant === "info" || variant === "success" ? "status" : "alert";
  return (
    <div
      className={clsx(className, classes.root, classes[`_${variant}`])}
      role={role}
      {...rest}
    >
      {children}
      {onClose && <RemoveButton onClick={onClose} />}
    </div>
  );
};

export default Banner;
